package com.bookflow.publiccatalog.application;
import com.bookflow.publiccatalog.api.PublicCatalogController.*; import org.springframework.context.annotation.Profile; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository @Profile("!test") public class PublicCatalogRepository {private final JdbcTemplate j;public PublicCatalogRepository(JdbcTemplate j){this.j=j;}public Optional<UUID> tenant(String s){return j.queryForList("SELECT id FROM businesses WHERE slug=? AND status='ACTIVE'",UUID.class,s).stream().findFirst();}public PublicBusiness business(UUID t){return j.query("SELECT slug,name,time_zone,currency_code FROM businesses WHERE id=?",rs->{rs.next();return new PublicBusiness(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4));},t);}public List<PublicBranch> branches(UUID t){return j.query("SELECT id,code,name,address_line1,city,time_zone FROM branches WHERE tenant_id=? AND status='ACTIVE' ORDER BY name,id",(r,n)->new PublicBranch(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)),t);}public boolean active(UUID t,UUID id,String table){return Boolean.TRUE.equals(j.queryForObject("SELECT EXISTS(SELECT 1 FROM "+table+" WHERE tenant_id=? AND id=? AND status='ACTIVE')",Boolean.class,t,id));}public boolean serviceInBranch(UUID t,UUID s,UUID b){return Boolean.TRUE.equals(j.queryForObject("SELECT EXISTS(SELECT 1 FROM branch_services WHERE tenant_id=? AND service_id=? AND branch_id=?)",Boolean.class,t,s,b));}public List<PublicService> services(UUID t,UUID b){String q=b==null?"SELECT id,name,description,price,currency,duration_minutes,buffer_before_minutes,buffer_after_minutes FROM services WHERE tenant_id=? AND status='ACTIVE' ORDER BY name,id":"SELECT DISTINCT s.id,s.name,s.description,s.price,s.currency,s.duration_minutes,s.buffer_before_minutes,s.buffer_after_minutes FROM services s JOIN branch_services x ON x.tenant_id=s.tenant_id AND x.service_id=s.id WHERE s.tenant_id=? AND s.status='ACTIVE' AND x.branch_id=? ORDER BY s.name,s.id";return b==null?j.query(q,this::service,t):j.query(q,this::service,t,b);}public List<PublicEmployee> employees(UUID t,UUID b,UUID s){String q=s==null?"SELECT DISTINCT e.id,e.full_name,e.bio FROM employees e JOIN employee_branch_assignments a ON a.tenant_id=e.tenant_id AND a.employee_id=e.id WHERE e.tenant_id=? AND e.status='ACTIVE' AND a.branch_id=? ORDER BY e.full_name,e.id":"SELECT DISTINCT e.id,e.full_name,e.bio FROM employees e JOIN employee_branch_assignments a ON a.tenant_id=e.tenant_id AND a.employee_id=e.id JOIN employee_services es ON es.tenant_id=e.tenant_id AND es.employee_id=e.id WHERE e.tenant_id=? AND e.status='ACTIVE' AND a.branch_id=? AND es.service_id=? ORDER BY e.full_name,e.id";return s==null?j.query(q,(r,n)->new PublicEmployee(r.getObject(1,UUID.class),r.getString(2),r.getString(3)),t,b):j.query(q,(r,n)->new PublicEmployee(r.getObject(1,UUID.class),r.getString(2),r.getString(3)),t,b,s);}private PublicService service(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new PublicService(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getInt(6),r.getInt(7),r.getInt(8));}}
